// art/sigils/strokes.js
var L = (...pts) => ({ l: pts });
var A = (cx, cy, r, from, to) => ({ a: [cx, cy, r, from, to] });
var D = (x, y) => ({ d: [x, y] });
var FOOT = A(0.5, 0.76, 0.13, 25, 155);
var mirror = (s) => s.l ? { l: s.l.map(([x, y]) => [1 - x, y]) } : s.a ? { a: [1 - s.a[0], s.a[1], s.a[2], 180 - s.a[3], 180 - s.a[4]] } : { d: [1 - s.d[0], s.d[1]] };
var pair = (...ss) => ss.flatMap((s) => [s, mirror(s)]);
function bow(p0, p1, k) {
  const dx = p1[0] - p0[0], dy = p1[1] - p0[1], c = Math.hypot(dx, dy), h = k * c, r = (c * c / 4 + h * h) / (2 * Math.abs(h));
  const mx = (p0[0] + p1[0]) / 2, my = (p0[1] + p1[1]) / 2, nx = dy / c, ny = -dx / c, off = (r - Math.abs(h)) * Math.sign(h);
  const cx = mx - nx * off, cy = my - ny * off, a0 = Math.atan2(p0[1] - cy, p0[0] - cx) * 180 / Math.PI;
  let a1 = Math.atan2(p1[1] - cy, p1[0] - cx) * 180 / Math.PI;
  let sweep = a1 - a0;
  while (sweep > 180) sweep -= 360;
  while (sweep < -180) sweep += 360;
  return A(cx, cy, r, a0, a0 + sweep);
}
var spiral = (cx, cy, r0, r1, turns, start = 0, n = 40) => L(...Array.from({ length: n + 1 }, (_, i) => {
  const t = i / n, a = (start + t * turns * 360) * Math.PI / 180, r = r0 + (r1 - r0) * t;
  return [cx + r * Math.cos(a), cy + r * Math.sin(a)];
}));
var rays = (cx, cy, r0, r1, angles) => angles.map((a) => {
  const c = Math.cos(a * Math.PI / 180), s = Math.sin(a * Math.PI / 180);
  return L([cx + r0 * c, cy + r0 * s], [cx + r1 * c, cy + r1 * s]);
});
var C = (cx, cy, r) => A(cx, cy, r, -90, 270);
var E = (cx, cy, rx, ry, a0 = -90, a1 = 270, n = 36) => L(...Array.from({ length: n + 1 }, (_, i) => {
  const a = (a0 + (a1 - a0) * i / n) * Math.PI / 180;
  return [cx + rx * Math.cos(a), cy + ry * Math.sin(a)];
}));
var at = (cx, cy, r, deg) => [cx + r * Math.cos(deg * Math.PI / 180), cy + r * Math.sin(deg * Math.PI / 180)];

