// config/house/shape.js
var hash = (x, y) => {
  const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
  return s - Math.floor(s);
};
function noise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y), xf = x - xi, yf = y - yi, u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hash(xi, yi), b = hash(xi + 1, yi), c = hash(xi, yi + 1), d = hash(xi + 1, yi + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
var fbm = (x, y) => noise(x, y) * 0.55 + noise(x * 2.1, y * 2.1) * 0.3 + noise(x * 4.3, y * 4.3) * 0.15;
function blob(r, x, z) {
  const dx = x - r.x, dz = z - r.z, a = Math.atan2(dz, dx), seed = r.x * 0.37 + r.z * 0.21;
  const rr = r.r * (1 + 0.1 * Math.sin(3 * a + seed) + 0.07 * Math.sin(5 * a + seed * 2.3) + 0.05 * (fbm(dx * 0.15 + seed, dz * 0.15) - 0.5) * 2);
  return Math.hypot(dx, dz) - rr;
}
function limbCurve(a, b, bend) {
  const L2 = Math.hypot(b.x - a.x, b.z - a.z), nx = -(b.z - a.z) / L2, nz = (b.x - a.x) / L2;
  return { a, b, c: { x: (a.x + b.x) / 2 + nx * bend * 2, z: (a.z + b.z) / 2 + nz * bend * 2 } };
}
var curveAt = (q, t) => ({ x: (1 - t) * (1 - t) * q.a.x + 2 * (1 - t) * t * q.c.x + t * t * q.b.x, z: (1 - t) * (1 - t) * q.a.z + 2 * (1 - t) * t * q.c.z + t * t * q.b.z });
var spineLimb = (a, b, i) => ({ a, b, bend: (i % 2 ? 1 : -1) * 1, w0: a.r * 0.82, w1: b.r * 0.82 });
var branchLimb = (p, r) => ({ a: p, b: r, bend: r.bend, w0: Math.min(5.5, p.r * 0.45), w1: Math.max(2.8, r.r * 0.42) });
function inMock(S) {
  if (S.m) return S.m;
  const [ox, oz] = S.noiseAt ?? [0, 0], mv = (r) => ({ ...r, x: r.x + ox, z: r.z + oz }), pt = (p) => ({ x: p.x + ox, z: p.z + oz });
  const trunk = S.trunk.map(mv), branches = S.branches.map(mv), byId = Object.fromEntries([...trunk, ...branches].map((r) => [r.id, r]));
  const all = [...trunk, ...branches], pad = 12;
  const box = { x0: Math.min(...all.map((r) => r.x - r.r * 1.3)) - pad, x1: Math.max(...all.map((r) => r.x + r.r * 1.3)) + pad, z0: Math.min(...all.map((r) => r.z - r.r * 1.3)) - pad, z1: Math.max(...all.map((r) => r.z + r.r * 1.3)) + pad };
  return S.m = { ox, oz, trunk, branches, byId, box, stubs: S.stubs.map((l) => ({ ...l, a: pt(l.a), b: pt(l.b) })) };
}
function inRoom(S0, id, x0, z0) {
  const S = inMock(S0), r = S.byId[id];
  return r ? blob(r, x0 + S.ox, z0 + S.oz) : 1e9;
}

// config/house/assemble.js
var f2 = (v) => +v.toFixed(2);
function houseShape(base, files) {
  const sorted = [...files].sort((a, b) => a.order - b.order), room = (f) => ({ id: f.id, x: f.x, z: f.z, r: f.r });
  const trunk = sorted.filter((f) => f.trunk).map(room), byId = Object.fromEntries(trunk.map((r) => [r.id, r]));
  const branches = sorted.filter((f) => f.from).map((f) => {
    if (!byId[f.from]) throw new Error(`house: ${f.id}'s branch leaves ${f.from}, which isn't a trunk room`);
    return { ...room(f), from: f.from, bend: f.bend ?? 0, ...f.locked ? { locked: true } : {} };
  });
  const stubs = branches.map((r) => {
    const q = limbCurve(byId[r.from], r, r.bend), a = Math.atan2(r.z - q.c.z, r.x - q.c.x), w = Math.max(2.8, r.r * 0.42), L2 = r.r + 2.5;
    return { room: r.id, a: { x: r.x, z: r.z }, b: { x: f2(r.x + Math.cos(a) * L2), z: f2(r.z + Math.sin(a) * L2) }, w0: f2(w * 0.9), w1: 1.4 };
  });
  return { noiseAt: base.noiseAt ?? [0, 0], trunk, branches, stubs };
}
function assemble(base, files) {
  const S = houseShape(base, files), byId = Object.fromEntries([...S.trunk, ...S.branches].map((r) => [r.id, r]));
  const sorted = [...files].sort((a, b) => a.order - b.order);
  const rooms = sorted.map((f) => ({
    id: f.id,
    label: f.label,
    x: f.x,
    z: f.z,
    x0: f2(f.x - f.r),
    x1: f2(f.x + f.r),
    z0: f2(f.z - f.r),
    z1: f2(f.z + f.r),
    r: f.r,
    ...f.trunk ? { trunk: true } : { from: f.from },
    ...f.locked ? { locked: true } : {}
  }));
  const doors = {}, corridors = [];
  const stretch = (id, l, upTo = 1) => {
    const q = limbCurve(l.a, l.b, l.bend), pts = [];
    for (let i = 0; i <= 8; i++) {
      const p = curveAt(q, i / 8 * upTo);
      pts.push([f2(p.x), f2(p.z)]);
    }
    const xs = pts.map((v) => v[0]), zs = pts.map((v) => v[1]), w = f2(l.w0 + l.w1);
    corridors.push({ id, x0: f2(Math.min(...xs) - w / 2), x1: f2(Math.max(...xs) + w / 2), z0: f2(Math.min(...zs) - w / 2), z1: f2(Math.max(...zs) + w / 2), w, pts });
  };
  for (let i = 1; i < S.trunk.length; i++) stretch(`${S.trunk[i - 1].id}-${S.trunk[i].id}`, spineLimb(S.trunk[i - 1], S.trunk[i], i));
  for (const r of S.branches) {
    const l = branchLimb(byId[r.from], r);
    if (!r.locked) {
      stretch(`${r.from}-${r.id}`, l);
      continue;
    }
    const q = limbCurve(l.a, l.b, l.bend);
    let t = 0;
    while (t < 1 && inRoom(S, r.id, curveAt(q, t).x, curveAt(q, t).z) > 0) t += 2e-3;
    const p = curveAt(q, t);
    doors[r.id] = { x: f2(p.x), z: f2(p.z) };
    stretch(`${r.from}-${r.id}`, l, t);
  }
  const objects = [];
  for (const f of sorted) {
    const p = byId[f.id];
    for (const o of f.objects ?? []) {
      const { offset, box, ...own } = o;
      objects.push({ ...own, room: f.id, x: f2(p.x + offset[0]), z: f2(p.z + offset[1]), w: box.w, d: box.d, h: box.h });
    }
    if (f.locked && f.door) {
      const { foot: [w, d, h], ...door } = f.door;
      objects.push({ id: `${f.id}Door`, room: f.from, ...door, ...doors[f.id], w, d, h });
    }
  }
  const { _: _note, noiseAt: _n, ...rest } = base;
  return { ...rest, rooms, corridors, objects, shape: S };
}

